;==============================================================================
; gear6.asm — 3E-T8 (R6 region, r6.asm rules; far6 only from other banks):
; hero_recalc (the ONLY writer of the hero's combat stats after hero_st_init),
; ench_any (GEAR3: the T12 Enchant scroll API), fx_line (a composed "<fx stem>
; <name>" log line), it_fmt (the page's stat line), and their data: the fx
; stems + it_stat (generated by tools/itempack.py from src/items.txt) and the
; per-type extras it_stat cannot carry (gx_tab). game.md §8 gear table, §8.6
; uniques, §8.11 "3E simplification" (fixed stats by type, ISTATE = m only).
;
; Stat model (hero_recalc):
;   atk  = KN_ATK / WZ_ATK + (LVL >= 4) + (LVL >= 8) + sum(gear ATK)
;   eva  = KN_EVA / WZ_EVA + (LVL >= 6) + sum(gear EVA, gx_tab)
;   die  = the worn weapon's die (fists FIST_DIE 1d2); bonus = its m (+1 the
;          Cleaver), SIGNED since 3F-T6 (do_attack / melee_hit roll
;          max(1, 1dN + bonus): a notched weapon at m < 0 hits for less, min 1)
;   DEF  = sum(gear DEF) + m of a worn armour / helm with DEF, clamped >= 0
;   max MP gear part = sum(gear MP) + m of a worn Robe / Hood (MP, no DEF),
;          >= 0; MAXMP += new - GEAR_MP (level-ups / tomes stay in MAXMP),
;          MP clamped to MAXMP (never raised: the start fill is kit_add's)
;   HERO_RES B0 / B1 = per-field max of the gear's (gx_tab), HERO_IMM = OR
;   MP_PER = 8 / 6 (class), / 2 with the Mana / Scarab amulet, x 2 with Plate
; Charms carry no m (only the weapon is enchanted; wear hits weapon / armour /
; helm). Rune / Bone staff spell damage (+1 / +2) is not a recalc stat: proj_prep
; (bank 3) reads the worn weapon's TYPE at cast time.
;==============================================================================

FIST_DIE        EQU 2                   ; game.md §8.7: an empty weapon slot = fists 1d2
IST_M_P3        EQU 3 << IST_M_SHIFT    ; m = +3: Enchant's cap ($60; bits 0-4 are 0)
GD_LEN          EQU 9                   ; gd_* / hr_* record (order below)

;------------------------------------------------------------------------------
; hero_recalc — rebuild the hero's derived stats from base + LVL + WORN (the
; model above). Event-driven: kit_add (new game), equip / remove (fx
; overlay), xp_level (a level gained), ench_any (a worn target), 3F wear.
; Writes kind_tab KT_ATK / KT_EVA / KT_DIE / KT_BONUS [HERO_KIND], HERO_DEF,
; HERO_RES (B0, B1), HERO_IMM, MAXMP / GEAR_MP / MP, MP_PER; PD_MP | PD_INFO.
; Clobbers: A, BC, DE, HL, F (IX kept).   ~2.5-4k T (4 worn items)
;------------------------------------------------------------------------------
hero_recalc:
                ld   hl, hr_die
                ld   b, GD_LEN
                xor  a
.z:             ld   (hl), a
                inc  hl
                djnz .z
                ld   hl, WORN
                ld   b, WORN_SLOTS
.s:             ld   a, (hl)
                or   a
                jr   z, .nx                    ; empty slot
                push bc
                push hl
                inc  l
                inc  l
                ld   c, (hl)                   ; ISTATE
                call gear_dec                  ; gd_* (A, BC, DE, HL)
                ld   de, gd_die
                ld   hl, hr_die
                ld   b, 6                      ; die, bonus, atk, DEF, MP, eva: sums
.ad:            ld   a, (de)                   ; (only the weapon slot has a die / bonus)
                add  a, (hl)
                ld   (hl), a
                inc  de
                inc  hl
                djnz .ad
                ld   b, 2                      ; RES B0, B1: per-field max
.rm:            ld   a, (de)
                call rmax
                inc  de
                inc  hl
                djnz .rm
                ld   a, (de)                   ; IMM: OR
                or   (hl)
                ld   (hl), a
                pop  hl
                pop  bc
.nx:            inc  l
                inc  l
                inc  l
                djnz .s
                ; --- base + the level steps (game.md §4.1: L4 / L8 atk, L6 eva) ---
                ld   a, (HERO_KIND)
                or   a
                ld   de, (KN_ATK << 8) | KN_EVA
                ld   c, MP_REG_W
                jr   z, .k
                ld   de, (WZ_ATK << 8) | WZ_EVA
                ld   c, MP_REG_M
.k:             ld   a, (LVL)
                cp   LVL_ATK1
                jr   c, .l
                inc  d
                cp   LVL_EVA1
                jr   c, .l
                inc  e
                cp   LVL_ATK2
                jr   c, .l
                inc  d
.l:             ld   a, (hr_atk)
                add  a, d
                ld   d, a                      ; D = atk
                ld   a, (hr_eva)
                add  a, e
                ld   e, a                      ; E = eva
                ld   a, (HERO_KIND)            ; the hero's kind_tab columns (one page)
                add  a, KT_ATK & $FF
                ld   l, a
                ld   h, kind_tab >> 8
                ld   (hl), d
                add  a, KT_EVA - KT_ATK
                ld   l, a
                ld   (hl), e
                add  a, KT_DIE - KT_EVA
                ld   l, a
                ld   a, (hr_die)
                or   a
                jr   nz, .dd
                ld   a, FIST_DIE               ; no weapon: fists
.dd:            ld   (hl), a
                ld   a, l
                add  a, KT_BONUS - KT_DIE
                ld   l, a
                ld   a, (hr_bon)               ; 3F-T6: SIGNED (a notched weapon, m < 0): the two melee rolls
                ld   (hl), a                   ; take max(1, 1dN + bonus)
                ld   a, (hr_def)
                call clamp0
                ld   (HERO_DEF), a
                ld   hl, (hr_r0)               ; L = B0, H = B1 (B2, the weak mask: no gear)
                ld   (HERO_RES), hl
                ld   a, (hr_imm)
                ld   (HERO_IMM), a
                ; --- MP regen period (C = the class's) ---
                ld   a, (WORN + WS_CHARM * IR_STRIDE)
                cp   IT_C_MANA
                jr   z, .h2
                cp   IT_C_SCARAB
                jr   nz, .nh
.h2:            srl  c                         ; regen x 2
.nh:            ld   a, (WORN + WS_ARMOUR * IR_STRIDE)
                cp   IT_A_PLATE
                jr   nz, .np
                sla  c                         ; Plate: regen x 1/2
.np:            ld   a, c
                ld   (MP_PER), a
                ; --- gear MP: MAXMP += new - old; MP <= MAXMP ---
                ld   a, (hr_mp)
                call clamp0
                ld   b, a
                ld   hl, GEAR_MP
                ld   a, (MAXMP)
                sub  (hl)
                add  a, b
                ld   (hl), b
                ld   (MAXMP), a
                ld   hl, MP
                cp   (hl)
                jr   nc, .mp
                ld   (hl), a                   ; clamp
.mp:            ld   hl, PANEL_DIRTY
                ld   a, (hl)
                or   PD_MP | PD_INFO
                ld   (hl), a
                ret
                ASSERT (kind_tab & $FF) == 0 && KT_ATK < KT_EVA && KT_EVA < KT_DIE && KT_DIE < KT_BONUS && KT_BONUS + K_MAX <= 256
                ASSERT LVL_ATK1 < LVL_EVA1 && LVL_EVA1 < LVL_ATK2 && MAXMP == MP + 1
                ASSERT HERO_IMM == HERO_RES + RES_LEN && (WORN & $FF) + WORN_SLOTS * IR_STRIDE <= 256

; clamp0 — A = max(A, 0) (signed).  Clobbers: F
clamp0:         bit  7, a
                ret  z
                xor  a
                ret

;------------------------------------------------------------------------------
; rmax — (HL) = the per-field max of (HL) and A (four 2-bit RSP_* fields:
; "best response wins"; an OR would turn R + I into X).
; Clobbers: A, C, F (B, DE, HL kept).
;------------------------------------------------------------------------------
rmax:           or   a
                ret  z                         ; nothing to merge (most gear): ~0.2k T saved
                push de
                ld   d, a
                ld   e, 3                      ; field mask
.f:             ld   a, d
                and  e
                ld   c, a                      ; new field
                ld   a, (hl)
                and  e                         ; old field (same shift: compare as is)
                cp   c
                jr   nc, .k
                ld   a, e
                cpl
                and  (hl)
                or   c
                ld   (hl), a
.k:             ld   a, e
                add  a, a
                add  a, a
                ld   e, a
                jr   nz, .f
                pop  de
                ret

;------------------------------------------------------------------------------
; ist_v — GEAR2: A = ISTATE -> A = v = m + q, signed (m = bits 5-7, q = bits 0-2,
; both 3-bit two's complement). One `xor $84` flips both sign bits, so each field
; reads as (field ^ 4) = field + 4 unsigned and the sum is off by 8:
; v = (m3 ^ 4) + (q3 ^ 4) - 8. The m field comes down by 3 x rlca (3 B, 12 T)
; instead of 5 x sra (10 B).
; Clobbers: A, H, L, F (B, C, DE kept).   ~100 T
;------------------------------------------------------------------------------
ist_v:
                xor  $84
                ld   l, a
                and  IST_Q_MASK
                ld   h, a                      ; H = q + 4
                ld   a, l
                rlca
                rlca
                rlca                           ; bits 5-7 -> 0-2
                and  7                         ; m + 4
                add  a, h
                sub  8
                ret
                ASSERT IST_Q_MASK == 7 && IST_M_SHIFT == 5 && IST_M_MASK == $E0

;------------------------------------------------------------------------------
; gear_dec — one gear item's own numbers into gd_die .. gd_imm (GD_LEN B):
; die (0 = not a weapon), dmg bonus (weapon v, +1 the Cleaver), atk, DEF (+ v
; when it has DEF), MP (+ v when it has no DEF: Robe / Hood), eva + RES B0 /
; B1 + IMM (gx_tab; zeros for a type without a row).
; In : A = type (gear), C = ISTATE.  Clobbers: A, BC, DE, HL, F.  ~0.5k T
;------------------------------------------------------------------------------
gear_dec:
                ld   b, a                      ; B = type
                add  a, a                      ; 2 * type < 88
                add  a, it_stat & $FF
                ld   l, a
                adc  a, it_stat >> 8
                sub  l
                ld   h, a
                ld   e, (hl)                   ; E = DIE | ATK << 4
                inc  hl
                ld   d, (hl)                   ; D = DEF | MP << 4
                ld   a, c
                call ist_v
                ld   c, a                      ; C = v = m + q (signed)
                ld   hl, gd_die
                ld   a, e
                and  $0F
                ld   (hl), a                   ; gd_die
                inc  hl
                jr   z, .nw
                ld   a, b
                cp   IT_W_CLEAVER
                ld   a, c                      ; weapon: dmg + v
                jr   nz, .wb
                inc  a                         ; the Cleaver's +1 (not packed)
.wb:            ld   c, 0                      ; v spent
                jr   .bon
.nw:            xor  a
.bon:           ld   (hl), a                   ; gd_bon
                inc  hl
                ld   a, e
                sra  a
                sra  a
                sra  a
                sra  a
                ld   (hl), a                   ; gd_atk (signed nibble)
                inc  hl
                ld   a, d
                and  $0F
                ; NB: v -> max MP for DEF-0 non-weapons (Might / Fire / Mana charms) is
                ; right only because a charm's ISTATE is 0 (q is generated 0, GEAR2; Enchant
                ; never picks one) and the 3F wear step must guard it (no m on a charm, else
                ; it would add MP). fx_equip has no class check (no room in the region).
                jr   z, .nd
                add  a, c                      ; armour / helm: DEF + v
                ld   c, 0
.nd:            ld   (hl), a                   ; gd_def
                inc  hl
                ld   a, d
                rrca
                rrca
                rrca
                rrca
                and  $0F
                add  a, c                      ; Robe / Hood: max MP + v
                ld   (hl), a                   ; gd_mp
                inc  hl
                ex   de, hl                    ; DE = gd_eva
                ld   hl, gx_tab
.x:             ld   a, (hl)
                inc  hl
                or   a
                jr   z, .h                     ; the end row: zeros
                cp   b
                jr   z, .h
                inc  hl
                inc  hl
                inc  hl
                inc  hl
                jr   .x
.h:             ld   bc, 4                     ; eva, B0, B1, IMM
                ldir
                ret
                ASSERT gd_bon == gd_die + 1 && gd_atk == gd_die + 2 && gd_def == gd_die + 3 && gd_mp == gd_die + 4
                ASSERT gd_eva == gd_die + 5 && gd_r0 == gd_die + 6 && gd_r1 == gd_die + 7 && gd_imm == gd_die + 8
                ASSERT IT_COUNT * 2 < 256

;------------------------------------------------------------------------------
; ench_any — GEAR3: the Enchant scroll's effect (gear_rules.md 3.1); fx_read
; prints the line and consumes the scroll either way, and it runs AFTER bag_take
; (the bag indices are the post-take ones).
; Candidates: numeric gear (IT_WPN_LO..IT_HELM_HI, never a charm) with m != +3,
; first the worn weapon / armour / helmet (slot order), only if none the bag (slot
; order). n >= 1: ONE gameplay rng_mod(n) picks the k-th; its m + 1 (q bits
; untouched); a worn target then hero_recalc. n = 0 in both: 0 draws.
; Out: A = the enchanted item's type, 0 = nothing (NOTHING HAPPENS).
; Clobbers: A, BC, DE, HL, F.   ~2.5k T (two scans) + hero_recalc for a worn one
;------------------------------------------------------------------------------
ench_any:
                ld   hl, WORN                  ; WS_WEAPON, WS_ARMOUR, WS_HELM (not the charm)
                ld   b, WS_CHARM
                call ea_pick
                or   a
                jr   nz, .w
                ld   hl, BAG
                ld   b, BAG_SLOTS
                jr   ea_pick                   ; a bag target: no recalc
.w:             push af
                call hero_recalc
                pop  af
                ret
                ASSERT WS_WEAPON == 0 && WS_HELM == 2 && WS_CHARM == 3

; ea_pick — HL = the first record, B = records: count the candidates (one scan),
; rng_mod(n), scan again to the k-th, m + 1.  Out: A = its type, 0 = no candidate
; (no draw).  Clobbers: A, BC, DE, HL, F.
ea_pick:
                push hl
                push bc
                ld   c, $FF                    ; no k reached: a pure count
                call ea_scan                   ; D = n
                pop  bc
                pop  hl
                ld   a, d
                or   a
                ret  z
                ld   c, a
                push hl
                push bc
                call rng_mod                   ; A = k (C = n; clobbers B, HL)
                pop  bc
                pop  hl
                ld   c, a
                call ea_scan                   ; Z, HL = the k-th's ISTATE
                ld   a, (hl)
                add  a, IST_M_ONE              ; m + 1 (m != +3: no carry out, q bits kept)
                ld   (hl), a
                dec  l
                dec  l
                ld   a, (hl)                   ; its type
                ret

; ea_scan — HL = the first record, B = records, C = k: walk the records; a
; candidate (type IT_WPN_LO..IT_HELM_HI, m != +3) is number D (0-based, counted in
; walk order). Out: Z + HL = &ISTATE of candidate k; or NZ + D = the number of
; candidates (C = $FF never matches). Clobbers: A, B, D, HL, F.
ea_scan:
                ld   d, 0
.l:             ld   a, (hl)                   ; type
                inc  l
                inc  l                         ; -> ISTATE (a page-aligned list: BAG / WORN)
                sub  IT_WPN_LO
                cp   IT_HELM_HI - IT_WPN_LO + 1
                jr   nc, .n                    ; empty / not weapon, armour or helmet
                ld   a, (hl)
                and  IST_M_MASK
                cp   IST_M_P3
                jr   z, .n                     ; already +3
                ld   a, d
                cp   c
                ret  z
                inc  d
.n:             inc  l
                djnz .l
                inc  b                         ; NZ
                ret
                ASSERT (BAG & $FF) == 0 && BAG_SLOTS * IR_STRIDE < 256 && (WORN & $FF) + WORN_SLOTS * IR_STRIDE <= 256
                ASSERT IT_WPN_LO == IT_W_SHORT && IT_HELM_HI + 1 == IT_CHARM_LO && IR_TYPE == 0 && IR_IST == 2

;------------------------------------------------------------------------------
; fx_line — a log line "<fx stem><name>" (game.md §8.11 text rulings (3)):
; the it_fx_stems stem at offset E (S_FX_*) into MSG_BUF, then bank-1
; it_line_nm adds item_name(A) (A = IT_NONE: the stem alone), terminates and
; log_push-es it (queued: safe inside an overlay; panel_tick draws it).
; In : A = type, E = S_FX_* offset.  Clobbers: A, BC, DE, HL, F.  ~2-6k T
;------------------------------------------------------------------------------
fx_line:
                push af
                ld   d, 0
                ld   hl, it_fx_stems
                add  hl, de
                ld   de, MSG_BUF
.c:             ld   a, (hl)
                or   a
                jr   z, .n
                ld   (de), a
                inc  hl
                inc  de
                jr   .c
.n:             pop  af
                ld   hl, it_line_nm            ; bank 1 (A, DE pass in)
                jp   far1
                ASSERT ITF_LEN < 256

;------------------------------------------------------------------------------
; it_fmt — the page's stat line (3E-T8, page_ovl pg_info, far6): the
; numbers of the item in slot A appended at DE, each " WORD+n": food
; " FOOD+n", Heal / Cure " HP+n", Mana " MP+n"; gear " 1Dn[+b]" (weapon:
; die and dmg bonus), " ATK+n", " DEF+n", " MP+n", " DODGE+n" (non-zero ones,
; signed); nothing for scrolls / books / the bow / an empty slot.
; In : A = slot 0..23 (record BAG + 3 * A), DE = dest. Out: DE past the text
; (no terminator; <= 27 chars: a gear item with v = m + q != 0 first gets " -n" /
; " +n", or " WORN OUT" in place at m = -3).  Clobbers: A, BC, HL, F.
;------------------------------------------------------------------------------
it_fmt:
                ld   c, a
                add  a, a
                add  a, c
                ld   l, a
                ld   h, HIGH BAG
                ld   a, (hl)                   ; type
                inc  l
                inc  l
                ld   c, (hl)                   ; ISTATE
                ld   b, a
                IT_IN IT_FOOD_LO, IT_POT_HI
                jr   nc, .g
                ld   a, b                      ; food / potion: the amount
                call it_amt                    ; (fx6.asm)
                ld   c, a                      ; C = amount
                ld   hl, fs_food
                ld   a, b
                cp   IT_POT_LO
                jr   c, .w
                ld   hl, fs_hp
                cp   IT_P_MANA
                jr   nz, .w
                ld   hl, fs_mp
.w:             ld   a, c
                jr   fopt
.g:             ld   a, b
                IT_IN IT_GEAR_LO, IT_GEAR_HI
                ret  nc
                ld   a, c
                and  IST_M_MASK
                cp   IST_M_M3
                jr   nz, .sg
                ld   hl, fs_worn               ; m = -3: " WORN OUT" in place of " v" (the next
                call fcat                      ; wear event destroys it; 3 chars shorter: the
                jr   .m0                       ; Cleaver's line is 37 chars, the row 40 wide)
.sg:            ld   a, c
                call ist_v                     ; GEAR2: v = m + q; 0 prints nothing
                or   a
                jr   z, .m0
                push bc
                ld   b, a
                ld   a, ' '
                ld   (de), a
                inc  de
                ld   a, b
                call fsgn                      ; " -2" / " +1" (wear-down and q show)
                pop  bc
.m0:            ld   a, b
                push de
                call gear_dec
                pop  de
                ld   a, (gd_die)
                or   a
                jr   z, .nd
                ld   hl, fs_die
                call fcat                      ; (A = 0 after it)
                ld   a, (gd_die)
                call msg_dec                   ; die sides
                ld   a, (gd_bon)
                or   a
                call nz, fsgn
.nd:            ld   a, (gd_atk)
                ld   hl, fs_atk
                call fopt
                ld   a, (gd_def)
                ld   hl, fs_def
                call fopt
                ld   a, (gd_mp)
                ld   hl, fs_mp
                call fopt
                ld   a, (gd_eva)
                ld   hl, fs_eva
                ; fall through
; fopt — A != 0: the word at HL + A signed.  Clobbers: A, BC, HL, F
fopt:           or   a
                ret  z
                push af
                call fcat
                pop  af
                ; fall through
; fsgn — A signed: '+' / '-' and |A| (0..99) at DE.  Clobbers: A, BC, F
fsgn:           ld   c, '+'
                or   a
                jp   p, .p
                neg
                ld   c, '-'
.p:             ld   b, a
                ld   a, c
                ld   (de), a
                inc  de
                ld   a, b
                ; fall through
                jp   msg_dec                   ; = fnum: A = 0..99 as 1-2 digits at DE (msg2.asm, bank 2,
                                               ; always mapped; the identical 21 B body was a copy here).
                                               ; Clobbers: A, BC, F
; fcat — copy the 0-terminated HL to DE (no 0).  Clobbers: A, HL, F.  msg_cat's copy loop
; (msg2.asm) is the same 8 B, so R6 does not carry its own.
fcat            EQU  msg_cat.c

fs_food:        DB   " FOOD", 0
fs_hp:          DB   " HP", 0
fs_mp:          DB   " MP", 0
fs_die:         DB   " 1D", 0
fs_atk:         DB   " ATK", 0
fs_def:         DB   " DEF", 0
fs_eva:         DB   " DODGE", 0               ; ITEM-INFO §2: the word the treasures page taught (was EVA)

; gx_tab — what it_stat cannot carry (game.md §8 / §8.6): type, eva, RES B0,
; RES B1 (RSP_* fields, combat_defs.asm), IMM; 5 B a row, a 0 type ends it.
gx_tab:         DB   IT_H_KING,   1, 0, 0, 0                                   ; eva +1
                DB   IT_A_SILK,   2, 0, 0, IMMF_POISON                         ; eva +2, poison-immune
                DB   IT_A_GRAVE,  0, 0, RSP_R | (RSP_R << 2), 0                ; DRAIN R, DARK R
                DB   IT_H_MIRROR, 0, 0, RSP_X << 2, 0                          ; DARK X
                DB   IT_C_FIRE,   0, RSP_R << 2, 0, 0                          ; FIRE R
                DB   IT_C_GRAVE,  0, 0, RSP_I << 2, 0                          ; DARK I
                DB   0, 0, 0, 0, 0
                ASSERT DTY_FIRE == 1 && DTY_DRAIN == 4 && DTY_DARK == 5

; variables (written in play; r6.asm rules: no SMC, tests/game.py #50 checks R6 at the menu)
gd_die:         DB   0                         ; gear_dec's record (GD_LEN)
gd_bon:         DB   0
gd_atk:         DB   0
gd_def:         DB   0
gd_mp:          DB   0
gd_eva:         DB   0
gd_r0:          DB   0
gd_r1:          DB   0
gd_imm:         DB   0
hr_die:         DS   GD_LEN                    ; hero_recalc's sums (same order)
hr_bon          EQU  hr_die + 1
hr_atk          EQU  hr_die + 2
hr_def          EQU  hr_die + 3
hr_mp           EQU  hr_die + 4
hr_eva          EQU  hr_die + 5
hr_r0           EQU  hr_die + 6
hr_imm          EQU  hr_die + 8

; the fx stems + it_stat (tools/itempack.py; S_FX_* / ITF_* in items_ids.inc)
                INCLUDE "../build/text/items_fx_stems.asm"
